class Solution:
    def minSteps(self, n: int) -> int:
        if n == 1:
            return 0

        dp = [0] + [float("inf")] * n

        for i in range(2, n + 1):
            for divisor in range(1, i):
                if i % divisor == 0:
                    dp[i] = min(dp[i], dp[divisor] + i // divisor)

        return dp[n]
