from typing import List

class Solution:
    def hitBricks(self, grid: List[List[int]], hits: List[List[int]]) -> List[int]:
        m, n = len(grid), len(grid[0])
        total = m * n
        roof = total

        parent = [-1] * (total + 1)
        size = [0] * (total + 1)

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a, b):
            ra, rb = find(a), find(b)
            if ra == rb:
                return
            if size[ra] < size[rb]:
                ra, rb = rb, ra
            parent[rb] = ra
            size[ra] += size[rb]

        existed = []
        for r, c in hits:
            existed.append(grid[r][c] == 1)
            if grid[r][c] == 1:
                grid[r][c] = 0

        for r in range(m):
            for c in range(n):
                if grid[r][c] == 1:
                    idx = r * n + c
                    parent[idx] = idx
                    size[idx] = 1

        parent[roof] = roof
        size[roof] = 0

        directions = ((1, 0), (-1, 0), (0, 1), (0, -1))

        for r in range(m):
            for c in range(n):
                if grid[r][c] == 1:
                    idx = r * n + c
                    if r == 0:
                        union(idx, roof)
                    if r + 1 < m and grid[r + 1][c] == 1:
                        union(idx, (r + 1) * n + c)
                    if c + 1 < n and grid[r][c + 1] == 1:
                        union(idx, r * n + c + 1)

        result = [0] * len(hits)

        for i in range(len(hits) - 1, -1, -1):
            if not existed[i]:
                continue

            r, c = hits[i]
            idx = r * n + c
            grid[r][c] = 1
            parent[idx] = idx
            size[idx] = 1

            if r == 0:
                union(idx, roof)

            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if 0 <= nr < m and 0 <= nc < n and grid[nr][nc] == 1:
                    union(idx, nr * n + nc)

            root = find(idx)
            if find(roof) == root:
                result[i] = size[root] - 1

        return result
