class Solution:
    def clumsy(self, n: int) -> int:
        stack = [n]
        operations = ("*", "/", "+", "-")

        for i, value in enumerate(range(n - 1, 0, -1)):
            op = operations[i % 4]
            if op == "*":
                stack[-1] *= value
            elif op == "/":
                stack[-1] //= value
            elif op == "+":
                stack.append(value)
            else:
                stack.append(-value)

        return sum(stack)
