from functools import lru_cache
from math import gcd

class Solution:
    def maxScore(self, nums: List[int]) -> int:
        m = len(nums)
        full_mask = (1 << m) - 1

        pair_gcd = [[gcd(nums[i], nums[j]) for j in range(m)] for i in range(m)]

        @lru_cache(None)
        def dp(mask: int) -> int:
            if mask == full_mask:
                return 0

            operation = mask.bit_count() // 2 + 1
            first = 0
            while mask & (1 << first):
                first += 1

            best = 0
            mask_with_first = mask | (1 << first)

            for second in range(first + 1, m):
                if not (mask & (1 << second)):
                    new_mask = mask_with_first | (1 << second)
                    score = operation * pair_gcd[first][second] + dp(new_mask)
                    best = max(best, score)

            return best

        return dp(0)
