from typing import List

class Solution:
    def minSessions(self, tasks: List[int], sessionTime: int) -> int:
        n = len(tasks)
        full = 1 << n
        dp = [(n + 1, n + 1)] * full
        dp[0] = (0, 0)

        for mask in range(full):
            sessions, used = dp[mask]

            for i in range(n):
                if not (mask & (1 << i)):
                    if used + tasks[i] <= sessionTime:
                        candidate = (sessions, used + tasks[i])
                    else:
                        candidate = (sessions + 1, tasks[i])

                    next_mask = mask | (1 << i)
                    if candidate < dp[next_mask]:
                        dp[next_mask] = candidate

        return dp[-1][0]
