from typing import List

class Solution:
    def removeInvalidParentheses(self, s: str) -> List[str]:
        left_remove = 0
        right_remove = 0

        for ch in s:
            if ch == '(':
                left_remove += 1
            elif ch == ')':
                if left_remove > 0:
                    left_remove -= 1
                else:
                    right_remove += 1

        result = []

        def dfs(index: int, left_rem: int, right_rem: int,
                balance: int, path: List[str]) -> None:
            if index == len(s):
                if left_rem == 0 and right_rem == 0 and balance == 0:
                    result.append(''.join(path))
                return

            ch = s[index]

            if ch == '(':
                if left_rem > 0 and not (
                    index > 0 and s[index - 1] == '(' and index > start_index
                ):
                    dfs(index + 1, left_rem - 1, right_rem, balance, path)

                path.append(ch)
                dfs(index + 1, left_rem, right_rem, balance + 1, path)
                path.pop()

            elif ch == ')':
                if right_rem > 0 and not (
                    index > 0 and s[index - 1] == ')' and index > start_index
                ):
                    dfs(index + 1, left_rem, right_rem - 1, balance, path)

                if balance > 0:
                    path.append(ch)
                    dfs(index + 1, left_rem, right_rem, balance - 1, path)
                    path.pop()

            else:
                path.append(ch)
                dfs(index + 1, left_rem, right_rem, balance, path)
                path.pop()

        start_index = 0
        dfs(0, left_remove, right_remove, 0, [])
        return result
