from typing import List
import heapq


class Solution:
    def medianSlidingWindow(self, nums: List[int], k: int) -> List[float]:
        small = []
        large = []
        delayed = {}
        small_size = 0
        large_size = 0

        def prune_small():
            while small:
                value = -small[0]
                if delayed.get(value, 0):
                    heapq.heappop(small)
                    delayed[value] -= 1
                    if delayed[value] == 0:
                        del delayed[value]
                else:
                    break

        def prune_large():
            while large:
                value = large[0]
                if delayed.get(value, 0):
                    heapq.heappop(large)
                    delayed[value] -= 1
                    if delayed[value] == 0:
                        del delayed[value]
                else:
                    break

        def rebalance():
            nonlocal small_size, large_size

            if small_size > large_size + 1:
                prune_small()
                heapq.heappush(large, -heapq.heappop(small))
                small_size -= 1
                large_size += 1
            elif small_size < large_size:
                prune_large()
                heapq.heappush(small, -heapq.heappop(large))
                large_size -= 1
                small_size += 1

        def add(value):
            nonlocal small_size, large_size

            if not small or value <= -small[0]:
                heapq.heappush(small, -value)
                small_size += 1
            else:
                heapq.heappush(large, value)
                large_size += 1
            rebalance()

        def remove(value):
            nonlocal small_size, large_size

            delayed[value] = delayed.get(value, 0) + 1
            prune_small()

            if small and value <= -small[0]:
                small_size -= 1
                if value == -small[0]:
                    prune_small()
            else:
                large_size -= 1
                if large and value == large[0]:
                    prune_large()

            rebalance()

        for value in nums[:k]:
            add(value)

        result = []

        for i in range(k, len(nums) + 1):
            prune_small()
            prune_large()

            if k % 2:
                result.append(float(-small[0]))
            else:
                result.append((-small[0] + large[0]) / 2.0)

            if i == len(nums):
                break

            remove(nums[i - k])
            add(nums[i])

        return result
```

