class Solution:
    def numFactoredBinaryTrees(self, arr: List[int]) -> int:
        MOD = 10**9 + 7
        arr.sort()
        present = set(arr)
        dp = {}

        for value in arr:
            ways = 1
            for left in arr:
                if left * left > value:
                    break
                if value % left == 0:
                    right = value // left
                    if right in present:
                        ways = (ways + dp[left] * dp[right]) % MOD
                        if left != right:
                            ways = (ways + dp[left] * dp[right]) % MOD
            dp[value] = ways

        return sum(dp.values()) % MOD
