class MKAverage:

    def __init__(self, m: int, k: int):
        self.m = m
        self.k = k
        self.limit = 100000
        self.window = []
        self.count_bit = [0] * (self.limit + 1)
        self.sum_bit = [0] * (self.limit + 1)

    def _update(self, value: int, delta: int) -> None:
        i = value
        while i <= self.limit:
            self.count_bit[i] += delta
            self.sum_bit[i] += delta * value
            i += i & -i

    def _prefix_count(self, index: int) -> int:
        result = 0
        while index > 0:
            result += self.count_bit[index]
            index -= index & -index
        return result

    def _prefix_sum(self, index: int) -> int:
        result = 0
        while index > 0:
            result += self.sum_bit[index]
            index -= index & -index
        return result

    def _kth(self, rank: int) -> int:
        index = 0
        bit = 1 << (self.limit.bit_length() - 1)

        while bit:
            next_index = index + bit
            if next_index <= self.limit and self.count_bit[next_index] < rank:
                index = next_index
                rank -= self.count_bit[next_index]
            bit >>= 1

        return index + 1

    def _sum_smallest(self, count: int) -> int:
        if count == 0:
            return 0

        value = self._kth(count)
        before_count = self._prefix_count(value - 1)
        before_sum = self._prefix_sum(value - 1)

        return before_sum + (count - before_count) * value

    def addElement(self, num: int) -> None:
        self.window.append(num)
        self._update(num, 1)

        if len(self.window) > self.m:
            removed = self.window.pop(0)
            self._update(removed, -1)

    def calculateMKAverage(self) -> int:
        if len(self.window) < self.m:
            return -1

        middle_sum = (
            self._sum_smallest(self.m - self.k)
            - self._sum_smallest(self.k)
        )

        return middle_sum // (self.m - 2 * self.k)
