class Solution:
    def largestMagicSquare(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])

        row_sum = [[0] * (n + 1) for _ in range(m)]
        col_sum = [[0] * n for _ in range(m + 1)]

        for i in range(m):
            for j in range(n):
                row_sum[i][j + 1] = row_sum[i][j] + grid[i][j]
                col_sum[i + 1][j] = col_sum[i][j] + grid[i][j]

        diag = [[0] * (n + 1) for _ in range(m + 1)]
        anti = [[0] * (n + 1) for _ in range(m + 1)]

        for i in range(m):
            for j in range(n):
                diag[i + 1][j + 1] = grid[i][j] + diag[i][j]

                rev_j = n - 1 - j
                anti[i + 1][rev_j + 1] = grid[i][j] + anti[i][rev_j]

        for size in range(min(m, n), 0, -1):
            for top in range(m - size + 1):
                for left in range(n - size + 1):
                    target = row_sum[top][left + size] - row_sum[top][left]

                    valid = True

                    for i in range(top + 1, top + size):
                        if row_sum[i][left + size] - row_sum[i][left] != target:
                            valid = False
                            break

                    if not valid:
                        continue

                    for j in range(left, left + size):
                        if col_sum[top + size][j] - col_sum[top][j] != target:
                            valid = False
                            break

                    if not valid:
                        continue

                    main_diag = diag[top + size][left + size] - diag[top][left]
                    if main_diag != target:
                        continue

                    rev_left = n - left - size
                    other_diag = (
                        anti[top + size][rev_left + size] - anti[top][rev_left]
                    )

                    if other_diag == target:
                        return size

        return 1
