class Solution:
    def maxTotalFruits(self, fruits: List[List[int]], startPos: int, k: int) -> int:
        n = len(fruits)
        prefix = [0] * (n + 1)

        for i in range(n):
            prefix[i + 1] = prefix[i] + fruits[i][1]

        def distance(left: int, right: int) -> int:
            left_pos = fruits[left][0]
            right_pos = fruits[right][0]

            if right_pos <= startPos:
                return startPos - left_pos
            if left_pos >= startPos:
                return right_pos - startPos

            left_dist = startPos - left_pos
            right_dist = right_pos - startPos
            return min(2 * left_dist + right_dist, left_dist + 2 * right_dist)

        ans = 0
        left = 0

        for right in range(n):
            while left <= right and distance(left, right) > k:
                left += 1

            if left <= right:
                ans = max(ans, prefix[right + 1] - prefix[left])

        return ans
