class Solution:
    def minMalwareSpread(self, graph: List[List[int]], initial: List[int]) -> int:
        n = len(graph)
        infected = [False] * n
        for node in initial:
            infected[node] = True

        visited = [False] * n
        saved = [0] * n

        for start in range(n):
            if infected[start] or visited[start]:
                continue

            stack = [start]
            visited[start] = True
            size = 0
            sources = set()

            while stack:
                node = stack.pop()
                size += 1

                for neighbor in range(n):
                    if not graph[node][neighbor]:
                        continue
                    if infected[neighbor]:
                        sources.add(neighbor)
                    elif not visited[neighbor]:
                        visited[neighbor] = True
                        stack.append(neighbor)

            if len(sources) == 1:
                source = next(iter(sources))
                saved[source] += size

        answer = initial[0]
        for node in initial[1:]:
            if saved[node] > saved[answer] or (
                saved[node] == saved[answer] and node < answer
            ):
                answer = node

        return answer
