class Solution:
    def minCost(self, maxTime: int, edges: List[List[int]], passingFees: List[int]) -> int:
        n = len(passingFees)
        graph = [[] for _ in range(n)]

        for x, y, time in edges:
            graph[x].append((y, time))
            graph[y].append((x, time))

        inf = float("inf")
        dp = [[inf] * n for _ in range(maxTime + 1)]
        dp[0][0] = passingFees[0]

        for current_time in range(maxTime + 1):
            for city in range(n):
                current_cost = dp[current_time][city]
                if current_cost == inf:
                    continue

                for next_city, travel_time in graph[city]:
                    next_time = current_time + travel_time
                    if next_time <= maxTime:
                        next_cost = current_cost + passingFees[next_city]
                        if next_cost < dp[next_time][next_city]:
                            dp[next_time][next_city] = next_cost

        answer = min(dp[time][n - 1] for time in range(maxTime + 1))
        return -1 if answer == inf else answer
