class Solution:
    def nextBeautifulNumber(self, n: int) -> int:
        answer = float("inf")

        for mask in range(1, 1 << 9):
            counts = [0] * 10
            length = 0

            for digit in range(1, 10):
                if mask & (1 << (digit - 1)):
                    counts[digit] = digit
                    length += digit

            if length > 7:
                continue

            def build(value: int, remaining: int) -> None:
                nonlocal answer

                if remaining == 0:
                    if value > n:
                        answer = min(answer, value)
                    return

                for digit in range(1, 10):
                    if counts[digit] > 0:
                        counts[digit] -= 1
                        build(value * 10 + digit, remaining - 1)
                        counts[digit] += 1

            build(0, length)

        return answer
