from typing import List
from functools import lru_cache

class Solution:
    def minStickers(self, stickers: List[str], target: str) -> int:
        m = len(target)
        full = (1 << m) - 1

        sticker_counts = []
        for sticker in stickers:
            count = [0] * 26
            for ch in sticker:
                count[ord(ch) - ord('a')] += 1
            sticker_counts.append(count)

        @lru_cache(None)
        def dp(mask: int) -> int:
            if mask == full:
                return 0

            first = 0
            while mask & (1 << first):
                first += 1

            first_char = ord(target[first]) - ord('a')
            best = float('inf')

            for sticker_count in sticker_counts:
                if sticker_count[first_char] == 0:
                    continue

                available = sticker_count[:]
                new_mask = mask

                for i, ch in enumerate(target):
                    if not (new_mask & (1 << i)):
                        idx = ord(ch) - ord('a')
                        if available[idx] > 0:
                            available[idx] -= 1
                            new_mask |= 1 << i

                best = min(best, 1 + dp(new_mask))

            return best

        result = dp(0)
        return -1 if result == float('inf') else result
