from typing import List
from functools import lru_cache


class Solution:
    def earliestAndLatest(self, n: int, firstPlayer: int, secondPlayer: int) -> List[int]:
        @lru_cache(None)
        def solve(players: int, a: int, b: int):
            if a + b == players + 1:
                return 1, 1

            possible = {(0, 0)}

            for i in range((players + 1) // 2):
                left = i + 1
                right = players - i

                if left == right:
                    winners = (left,)
                elif left == a or right == a:
                    winners = (a,)
                elif left == b or right == b:
                    winners = (b,)
                else:
                    winners = (left, right)

                next_possible = set()
                for count_a, count_b in possible:
                    for winner in winners:
                        next_possible.add(
                            (
                                count_a + (winner < a),
                                count_b + (winner < b),
                            )
                        )
                possible = next_possible

            next_players = (players + 1) // 2
            earliest = float("inf")
            latest = 0

            for count_a, count_b in possible:
                next_a = count_a + 1
                next_b = count_b + 1
                e, l = solve(next_players, next_a, next_b)
                earliest = min(earliest, e + 1)
                latest = max(latest, l + 1)

            return earliest, latest

        return list(solve(n, firstPlayer, secondPlayer))
